static int zh_lookup(unsigned short cp)
{
    int lo = 0, hi = ZH_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (zh_cps[mid] == cp) return mid;
        if (zh_cps[mid] < cp) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}
